    entries: [
      {
        asset: { type: Schema.Types.ObjectId, ref: 'Asset', required: true },
        position: { type: Number, default: 0 },
        startAtSeconds: { type: Number, default: 0 },
        addedBy: { type: Schema.Types.ObjectId, ref: 'User' },
        _id: false,
      },
    ],
  },
  { timestamps: true },
);

const CommentSchema = new Schema(
  {
